import backtrader as bt


class IntradayBreakoutStrategy(bt.Strategy):
    params = (
        ('period', 20),
        ('stop_loss_pct', 0.02),
    )

    def __init__(self):
        self.sma = bt.indicators.SMA(self.data.close, period=self.p.period)
        self.stddev = bt.indicators.StdDev(self.data.close, period=self.p.period)
        self.upper_band = self.sma + self.stddev
        self.lower_band = self.sma - self.stddev

        self.order = None
        self.entry_price = None

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return

        if order.status in [order.Completed]:
            if self.position:
                self.entry_price = self.position.price
            else:
                self.entry_price = None

        self.order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.data.close[0] > self.upper_band[0] and self.data.close[-1] <= self.upper_band[-1]:
                self.order = self.buy()
            elif self.data.close[0] < self.lower_band[0] and self.data.close[-1] >= self.lower_band[-1]:
                self.order = self.sell()
        else:
            entry_price = self.entry_price if self.entry_price is not None else self.position.price
            if self.position.size > 0:
                stop_price = entry_price * (1.0 - self.p.stop_loss_pct)
                if self.data.close[0] < self.sma[0] or self.data.low[0] <= stop_price:
                    self.order = self.close()
            elif self.position.size < 0:
                stop_price = entry_price * (1.0 + self.p.stop_loss_pct)
                if self.data.close[0] > self.sma[0] or self.data.high[0] >= stop_price:
                    self.order = self.close()
